import com.android.tools.smali.dexlib2.*;import com.android.tools.smali.dexlib2.iface.*;import com.android.tools.smali.dexlib2.iface.instruction.*;import java.io.*;import java.util.*;
class CompareNative {
 static ClassDef cls(String apk,String type)throws Exception {var c=DexFileFactory.loadDexContainer(new File(apk),Opcodes.getDefault());for(var e:c.getDexEntryNames())for(var x:c.getEntry(e).getDexFile().getClasses())if(x.getType().equals(type))return x;throw new AssertionError(type);}
 static String code(Instruction x){String s=x.getOpcode().toString();if(x instanceof ReferenceInstruction r)s+=" "+r.getReference();if(x instanceof WideLiteralInstruction r)s+=" #"+r.getWideLiteral();if(x instanceof OffsetInstruction r)s+=" @"+r.getCodeOffset();if(x instanceof OneRegisterInstruction r)s+=" a"+r.getRegisterA();if(x instanceof TwoRegisterInstruction r)s+=" b"+r.getRegisterB();if(x instanceof ThreeRegisterInstruction r)s+=" c"+r.getRegisterC();if(x instanceof FiveRegisterInstruction r)s+=" regs"+r.getRegisterCount()+":"+r.getRegisterC()+","+r.getRegisterD()+","+r.getRegisterE()+","+r.getRegisterF()+","+r.getRegisterG();if(x instanceof RegisterRangeInstruction r)s+=" range"+r.getStartRegister()+":"+r.getRegisterCount();return s;}
 static List<String> code(Method m){List<String>r=new ArrayList<>();if(m.getImplementation()!=null)m.getImplementation().getInstructions().forEach(x->r.add(code(x)));return r;}
 public static void main(String[]a)throws Exception {ClassDef original=cls(a[0],"Lajto;"),patched=cls(a[1],"Lajto;");int n=0;for(Method m:original.getMethods()){Method found=null;for(Method p:patched.getMethods())if(p.toString().equals(m.toString()))found=p;if(found==null||!code(m).equals(code(found)))throw new AssertionError("native footer method changed "+m);n++;}System.out.println("PASS "+n+" original native footer methods unchanged (rendering/lifecycle); only upstream model binder patched");}
}
